    const sync=(from,to)=>()=>{if(syncing)return;syncing=true;to.scrollLeft=from.scrollLeft;rail.setAttribute('aria-valuenow',String(Math.round(wrap.scrollLeft)));requestAnimationFrame(()=>{syncing=false})};const topSync=sync(rail,wrap),bottomSync=sync(wrap,rail);rail.addEventListener('scroll',topSync,{passive:true});wrap.addEventListener('scroll',bottomSync,{passive:true});const resize=new ResizeObserver(size);resize.observe(wrap);resize.observe(q('table',wrap)||wrap);size();routeCleanup.push(()=>{resize.disconnect();rail.remove();wrap.removeEventListener('scroll',bottomSync);rail.removeEventListener('scroll',topSync);delete wrap.dataset.teghScrollRail})
